#include <stdio.h>

int main(void) {
    int vals[] = {7, -7, 8, -8, 1, -1};
    unsigned i;

    printf("=== arithmetic shift vs division in C ===\n");
    printf("     x   x>>1    x/2    x<<1    x*2\n");
    for (i = 0; i < sizeof vals / sizeof vals[0]; i++) {
        int x = vals[i];
        /* x<<1 用无符号做，避免有符号左移的 UB；x*2 在这里不会溢出 */
        printf("  %4d   %4d   %5d   %5d   %5d\n",
               x, x >> 1, x / 2, (int)((unsigned)x << 1), x * 2);
    }

    printf("\nnotes:\n");
    printf("  for negative odd x, x>>1 floors toward -inf but x/2 truncates toward 0\n");
    printf("    -7 >> 1 = -4   while   -7 / 2 = -3\n");
    printf("  signed right shift is IMPLEMENTATION-DEFINED (gcc: arithmetic); unsigned is always logical\n");
    printf("  left-shifting a signed value that overflows is UNDEFINED BEHAVIOUR -> write 1u << n\n");

    printf("\n=== logical shift on unsigned ===\n");
    unsigned u = 0x80000000u;
    unsigned char c = 0x80u;
    printf("  u = %08X   u >> 1 = %08X   (zeroes shift in from the left)\n", u, u >> 1);
    printf("  (unsigned char)0x80 >> 1 = %02X\n", (unsigned)(unsigned char)(c >> 1));

    printf("\n=== rounding direction summary ===\n");
    printf("  x >> 1 (signed, gcc) floors        -> use when you mean 'divide by 2, rounding down'\n");
    printf("  x / 2 (C99)          truncates     -> use when you mean 'integer division'\n");
    return 0;
}
